message.content:
{"diagnosis": "Fetch test traps with TRAP: no progress max_addr=0x00000000 and tohost FAIL 0xdead instead of advancing through 256 NOP words. The default assignment set_mem_do_wdata = 1 at picorv32.v:1408 holds the memory interface in write-phase instead of expected 0. This blocks launch_next_insn and cpu_state_fetch progress so max_addr never advances.", "patch_diff": "diff --git a/picorv32.v b/picorv32.v
--- a/picorv32.v
+++ b/picorv32.v
@@ -1406,3 +1406,3 @@
 		set_mem_do_rinst = 0;
 		set_mem_do_rdata = 0;
-		set_mem_do_wdata = 1;
+		set_mem_do_wdata = 0;
", "expected": "tohost PASS (not FAIL 0xdead), no TRAP: no progress, max_addr != 0x00000000 with forward fetch progress"}

